import { sql, type SQL } from "drizzle-orm";
import { timestamp, uuid, type AnyPgColumn } from "drizzle-orm/pg-core";

/**
 * Primary key generated by PostgreSQL 18's uuidv7().
 * UUIDv7 values start with a timestamp, so new rows go to the end of the index.
 * That keeps inserts fast on big tables, unlike fully random UUIDs.
 */
export const primaryId = () =>
  uuid()
    .primaryKey()
    .default(sql`uuidv7()`);

/** When the row was created. Stored in UTC (BR-8). */
export const createdAt = () => timestamp({ withTimezone: true }).notNull().defaultNow();

const SAFE_VALUE = /^[A-Za-z_]+$/;

/**
 * SQL for a CHECK constraint that limits a text column to a fixed list.
 * The list comes from the domain layer, so TypeScript and the database always agree.
 *
 * We use text + CHECK instead of a PostgreSQL ENUM type, because CHECK lists are easy
 * to change in a migration, while ENUM values cannot be removed.
 */
export function oneOf(column: AnyPgColumn, values: readonly string[]): SQL {
  for (const value of values) {
    if (!SAFE_VALUE.test(value)) {
      throw new Error(`Unsafe value in CHECK list: ${value}`);
    }
  }
  return sql`${column} IN (${sql.raw(values.map((value) => `'${value}'`).join(", "))})`;
}
